import {
  empty_prefs,
  type CharacterKey,
  type CharacterPrefs,
  type InstructionFolder,
  type InstructionItem,
  type ShotMeta,
  type TextItem,
} from './types';

/**
 * 本地收藏库。
 *
 * 全部数据存在浏览器的 IndexedDB 里，不上传任何服务器。
 * 截图的大图单独放在 shot_blobs，列表查询只读元信息与缩略图，
 * 否则手机上一打开图库就会把所有原图读进内存。
 */

const DB_NAME = 'yueji-guanjia';
const DB_VERSION = 1;

const STORE_TEXTS = 'texts';
const STORE_SHOTS = 'shots';
const STORE_SHOT_BLOBS = 'shot_blobs';
const STORE_FOLDERS = 'instruction_folders';
const STORE_INSTRUCTIONS = 'instructions';
const STORE_PREFS = 'character_prefs';

export function new_id(): string {
  const api = globalThis.crypto;
  if (api && typeof api.randomUUID === 'function') return api.randomUUID();
  return `yj-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function upgrade(db: IDBDatabase): void {
  if (!db.objectStoreNames.contains(STORE_TEXTS)) {
    const store = db.createObjectStore(STORE_TEXTS, { keyPath: 'id' });
    store.createIndex('character_key', 'character_key');
    store.createIndex('created_at', 'created_at');
  }
  if (!db.objectStoreNames.contains(STORE_SHOTS)) {
    const store = db.createObjectStore(STORE_SHOTS, { keyPath: 'id' });
    store.createIndex('character_key', 'character_key');
    store.createIndex('created_at', 'created_at');
  }
  if (!db.objectStoreNames.contains(STORE_SHOT_BLOBS)) {
    db.createObjectStore(STORE_SHOT_BLOBS, { keyPath: 'id' });
  }
  if (!db.objectStoreNames.contains(STORE_FOLDERS)) {
    const store = db.createObjectStore(STORE_FOLDERS, { keyPath: 'id' });
    store.createIndex('created_at', 'created_at');
  }
  if (!db.objectStoreNames.contains(STORE_INSTRUCTIONS)) {
    const store = db.createObjectStore(STORE_INSTRUCTIONS, { keyPath: 'id' });
    store.createIndex('folder_id', 'folder_id');
    store.createIndex('created_at', 'created_at');
  }
  if (!db.objectStoreNames.contains(STORE_PREFS)) {
    db.createObjectStore(STORE_PREFS, { keyPath: 'character_key' });
  }
}

let db_promise: Promise<IDBDatabase> | null = null;

export function open_db(): Promise<IDBDatabase> {
  if (db_promise) return db_promise;
  db_promise = new Promise<IDBDatabase>((resolve, reject) => {
    const factory = globalThis.indexedDB;
    if (!factory) {
      reject(new Error('当前环境不支持本地数据库'));
      return;
    }
    let request: IDBOpenDBRequest;
    try {
      request = factory.open(DB_NAME, DB_VERSION);
    } catch (error) {
      reject(error instanceof Error ? error : new Error('打开本地数据库失败'));
      return;
    }
    request.onupgradeneeded = () => {
      upgrade(request.result);
    };
    request.onsuccess = () => {
      resolve(request.result);
    };
    request.onerror = () => {
      reject(request.error ?? new Error('打开本地数据库失败'));
    };
    request.onblocked = () => {
      reject(new Error('本地数据库被酒馆的其他标签页占用，请关掉多余标签页再试'));
    };
  });
  // 失败之后不要留下一个永远失败的缓存，否则用户重试也没救。
  db_promise.catch(() => {
    db_promise = null;
  });
  return db_promise;
}

/** 只读一个请求，resolve 时给出结果。 */
function read_request<T>(names: string[], make_request: (tx: IDBTransaction) => IDBRequest<T>): Promise<T> {
  return open_db().then(
    db =>
      new Promise<T>((resolve, reject) => {
        const tx = db.transaction(names, 'readonly');
        let request: IDBRequest<T>;
        try {
          request = make_request(tx);
        } catch (error) {
          reject(error instanceof Error ? error : new Error('读取本地数据失败'));
          return;
        }
        request.onsuccess = () => {
          resolve(request.result);
        };
        request.onerror = () => {
          reject(request.error ?? new Error('读取本地数据失败'));
        };
        tx.onabort = () => {
          reject(tx.error ?? new Error('读取本地数据被中止'));
        };
      }),
  );
}

/** 写操作。整个过程放在一个事务里，避免截图的元信息和大图对不上。 */
function write_transaction(names: string[], work: (tx: IDBTransaction) => void): Promise<void> {
  return open_db().then(
    db =>
      new Promise<void>((resolve, reject) => {
        const tx = db.transaction(names, 'readwrite');
        tx.oncomplete = () => {
          resolve();
        };
        tx.onerror = () => {
          reject(tx.error ?? new Error('保存本地数据失败'));
        };
        tx.onabort = () => {
          reject(tx.error ?? new Error('保存本地数据被中止'));
        };
        try {
          work(tx);
        } catch (error) {
          try {
            tx.abort();
          } catch {
            // 事务可能已经结束，忽略。
          }
          reject(error instanceof Error ? error : new Error('保存本地数据失败'));
        }
      }),
  );
}

function by_created_desc<T extends { created_at: number }>(items: T[]): T[] {
  return [...items].sort((a, b) => b.created_at - a.created_at);
}

/* ------------------------------------------------------------------ 文本收藏 */

export async function list_texts(character_key: CharacterKey): Promise<TextItem[]> {
  const items = await read_request<TextItem[]>([STORE_TEXTS], tx =>
    tx.objectStore(STORE_TEXTS).index('character_key').getAll(character_key),
  );
  return by_created_desc(items ?? []);
}

export function put_text(item: TextItem): Promise<void> {
  return write_transaction([STORE_TEXTS], tx => {
    tx.objectStore(STORE_TEXTS).put(item);
  });
}

export function delete_text(id: string): Promise<void> {
  return write_transaction([STORE_TEXTS], tx => {
    tx.objectStore(STORE_TEXTS).delete(id);
  });
}

/* ------------------------------------------------------------------ 截图 */

export async function list_shots(character_key: CharacterKey): Promise<ShotMeta[]> {
  const items = await read_request<ShotMeta[]>([STORE_SHOTS], tx =>
    tx.objectStore(STORE_SHOTS).index('character_key').getAll(character_key),
  );
  return by_created_desc(items ?? []);
}

export function put_shot(meta: ShotMeta, image: Blob): Promise<void> {
  return write_transaction([STORE_SHOTS, STORE_SHOT_BLOBS], tx => {
    tx.objectStore(STORE_SHOTS).put(meta);
    tx.objectStore(STORE_SHOT_BLOBS).put({ id: meta.id, image });
  });
}

export async function get_shot_image(id: string): Promise<Blob | null> {
  const record = await read_request<{ id: string; image: Blob } | undefined>([STORE_SHOT_BLOBS], tx =>
    tx.objectStore(STORE_SHOT_BLOBS).get(id),
  );
  return record?.image ?? null;
}

export function set_shot_starred(id: string, starred: boolean): Promise<void> {
  return write_transaction([STORE_SHOTS], tx => {
    const store = tx.objectStore(STORE_SHOTS);
    const request = store.get(id);
    request.onsuccess = () => {
      const meta = request.result as ShotMeta | undefined;
      if (!meta) return;
      meta.starred = starred;
      store.put(meta);
    };
  });
}

export function delete_shot(id: string): Promise<void> {
  return write_transaction([STORE_SHOTS, STORE_SHOT_BLOBS], tx => {
    tx.objectStore(STORE_SHOTS).delete(id);
    tx.objectStore(STORE_SHOT_BLOBS).delete(id);
  });
}

/* ------------------------------------------------------------------ 番外指令 */

export async function list_folders(): Promise<InstructionFolder[]> {
  const items = await read_request<InstructionFolder[]>([STORE_FOLDERS], tx => tx.objectStore(STORE_FOLDERS).getAll());
  return [...(items ?? [])].sort((a, b) => a.created_at - b.created_at);
}

export function put_folder(folder: InstructionFolder): Promise<void> {
  return write_transaction([STORE_FOLDERS], tx => {
    tx.objectStore(STORE_FOLDERS).put(folder);
  });
}

/** 删文件夹时把它下面的指令移到「未分类」，不连坐删掉用户的内容。 */
export function delete_folder(id: string): Promise<void> {
  return write_transaction([STORE_FOLDERS, STORE_INSTRUCTIONS], tx => {
    const instructions = tx.objectStore(STORE_INSTRUCTIONS);
    const cursor_request = instructions.index('folder_id').openCursor(IDBKeyRange.only(id));
    cursor_request.onsuccess = () => {
      const cursor = cursor_request.result;
      if (!cursor) return;
      const value = cursor.value as InstructionItem;
      value.folder_id = null;
      cursor.update(value);
      cursor.continue();
    };
    tx.objectStore(STORE_FOLDERS).delete(id);
  });
}

export async function list_instructions(): Promise<InstructionItem[]> {
  const items = await read_request<InstructionItem[]>([STORE_INSTRUCTIONS], tx =>
    tx.objectStore(STORE_INSTRUCTIONS).getAll(),
  );
  return by_created_desc(items ?? []);
}

export function put_instruction(item: InstructionItem): Promise<void> {
  return write_transaction([STORE_INSTRUCTIONS], tx => {
    tx.objectStore(STORE_INSTRUCTIONS).put(item);
  });
}

export function delete_instruction(id: string): Promise<void> {
  return write_transaction([STORE_INSTRUCTIONS], tx => {
    tx.objectStore(STORE_INSTRUCTIONS).delete(id);
  });
}

/* ------------------------------------------------------------------ 角色偏好 */

export async function get_prefs(character_key: CharacterKey): Promise<CharacterPrefs> {
  const record = await read_request<CharacterPrefs | undefined>([STORE_PREFS], tx =>
    tx.objectStore(STORE_PREFS).get(character_key),
  );
  return record ?? empty_prefs(character_key);
}

export function put_prefs(prefs: CharacterPrefs): Promise<void> {
  return write_transaction([STORE_PREFS], tx => {
    tx.objectStore(STORE_PREFS).put(prefs);
  });
}

/* ------------------------------------------------------------------ 备份 */

export interface TextBackup {
  format: 'yueji-guanjia-backup';
  version: 1;
  exported_at: number;
  texts: TextItem[];
  folders: InstructionFolder[];
  instructions: InstructionItem[];
  prefs: CharacterPrefs[];
}

/**
 * 导出文字类备份。
 * 按作者的要求，图片不进备份，只留在插件内的截图库里。
 */
export async function export_text_backup(): Promise<TextBackup> {
  const [texts, folders, instructions, prefs] = await Promise.all([
    read_request<TextItem[]>([STORE_TEXTS], tx => tx.objectStore(STORE_TEXTS).getAll()),
    read_request<InstructionFolder[]>([STORE_FOLDERS], tx => tx.objectStore(STORE_FOLDERS).getAll()),
    read_request<InstructionItem[]>([STORE_INSTRUCTIONS], tx => tx.objectStore(STORE_INSTRUCTIONS).getAll()),
    read_request<CharacterPrefs[]>([STORE_PREFS], tx => tx.objectStore(STORE_PREFS).getAll()),
  ]);
  return {
    format: 'yueji-guanjia-backup',
    version: 1,
    exported_at: Date.now(),
    texts: texts ?? [],
    folders: folders ?? [],
    instructions: instructions ?? [],
    prefs: prefs ?? [],
  };
}
