import type { TavernContext } from '../tavern/env';
import { avatar_key, NO_CHARACTER, type CharacterKey } from './types';

/**
 * 角色归属。
 * 酒馆官方类型声明里写明 avatar 就是角色卡的唯一标识，所以收藏按它隔离，改名不影响。
 */

export function current_character_key(context: TavernContext | null): CharacterKey {
  const avatar = current_avatar(context);
  return avatar ? avatar_key(avatar) : NO_CHARACTER;
}

export function current_avatar(context: TavernContext | null): string | null {
  const characters = context?.characters ?? [];
  const index = Number(context?.characterId);
  if (!Number.isFinite(index)) return null;
  const avatar = characters[index]?.avatar;
  return typeof avatar === 'string' && avatar ? avatar : null;
}

export function current_character_name(context: TavernContext | null): string {
  const characters = context?.characters ?? [];
  const index = Number(context?.characterId);
  if (!Number.isFinite(index)) return '';
  return characters[index]?.name ?? '';
}

/** 归属键转成能显示的名字。用于图库、文本库里标注来源。 */
export function describe_key(key: CharacterKey, context: TavernContext | null = null): string {
  if (key === NO_CHARACTER) return '未指定角色';
  if (key.startsWith('avatar:')) {
    const avatar = key.slice('avatar:'.length);
    const found = (context?.characters ?? []).find(item => item.avatar === avatar);
    return found?.name ?? avatar;
  }
  return key;
}
